//! 📮️ One distinct Source claim pays the final actual header-cell exposure bit.
use super::*;
fn bad()->ValueError{refused("header exposure changed its actual Source, cell or permit")}
use semio_framework_job_return_escrow_publication::OriginalEscrowHeaderLoanCell;
/// 🎟️ This stable Entry slot cannot substitute the physical Deallocate guard.
pub struct OriginalHeaderExposurePermit{place:crate::OriginalCallerReturnPlace,owner:usize,source:usize,destination:usize}
impl OriginalHeaderExposurePermit{pub const fn empty()->Self{Self{place:crate::OriginalCallerReturnPlace::empty(),owner:0,source:0,destination:0}}pub fn terminal_is_empty(&self)->bool{self.owner==0&&self.source==0&&self.destination==0&&self.place.terminal_is_empty()}}
fn identity(permit:&OriginalHeaderExposurePermit)->Result<(),OriginalTurnFailure>{if permit.owner!=permit as*const _ as usize{return Err(bad().into())}Ok(())}
fn metadata(cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let bytes=3*size_of::<usize>();let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0||cx.fuel_remaining()==0{return Ok(false)}cx.consume_retained(P{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
/// 🌱️ Binds one real Source return claim to the actual cell before its first published snapshot.
pub fn prepare_original_header_exposure(cx:&mut StepContext<'_>,permit:&mut OriginalHeaderExposurePermit,cell:&OriginalEscrowHeaderLoanCell)->Result<bool,OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;let source=parent.source_identity()?;let(destination,extent)=cell.exposure_destination();let address=permit as*mut _ as usize;if permit.owner==0{if !metadata(cx)?{return Ok(false)}permit.owner=address;permit.source=source;permit.destination=destination;return Ok(false)}identity(permit)?;if permit.source!=source||permit.destination!=destination{return Err(bad().into())}if cell.is_exposed(){return Err(bad().into())}let(destination,extent)=cell.exposure_destination();if !permit.place.is_admitted(){return permit.place.admit_sized(cx,destination,extent).map(|_|false)}if !permit.place.capture_is_preissued(){return permit.place.preissue_capture(cx,destination,extent)}permit.place.qualify_sized(cx,destination,extent)?;Ok(true)}
impl OriginalReturnSource{
 /// ⚡️ Every fallible check precedes the one infallible actual exposed-bit write and checked Core word.
 pub fn expose_original_header(&self,permit:&OriginalHeaderExposurePermit,cell:&mut OriginalEscrowHeaderLoanCell)->Result<u64,ValueError>{identity(permit).map_err(|_|bad())?;let budget=self.try_borrow().ok_or_else(||bad())?;let b=budget.get();let origin=b.origin().ok_or_else(||bad())?;if origin.recipient!=b as*const _ as usize||b.publication.is_none()||b.publisher_fenced{return Err(bad())}let(destination,extent)=cell.exposure_destination();permit.place.qualify_preissued_budget(b,destination,extent)?;if permit.source!=origin.source||permit.destination!=destination{return Err(bad())}let publisher=b.publisher().ok_or_else(||bad())?;let commit=cell.prepare_exposure(publisher)?;Ok(commit.commit())}
}
impl crate::OriginalCallerSourceParent{pub fn expose_original_header(&self,permit:&OriginalHeaderExposurePermit,cell:&mut OriginalEscrowHeaderLoanCell)->Result<u64,ValueError>{self.return_source()?.expose_original_header(permit,cell)}}
/// 🧾️ The Source observes only an actual committed bit, independently of later physical header return.
pub fn observe_original_header_exposure(cx:&mut StepContext<'_>,permit:&mut OriginalHeaderExposurePermit,cell:&OriginalEscrowHeaderLoanCell)->Result<bool,OriginalTurnFailure>{if permit.terminal_is_empty(){return Ok(true)}identity(permit)?;validate_observer(cx,permit,cell)?;if !cell.is_exposed(){return Err(bad().into())}let(destination,extent)=cell.exposure_destination();if !permit.place.terminal_is_empty(){permit.place.qualify_sized(cx,destination,extent)?;if !permit.place.settle_return(cx)?{return Ok(false)}}if !metadata(cx)?{return Ok(false)}permit.owner=0;permit.source=0;permit.destination=0;Ok(true)}
/// ↩️ Cancellation returns a genuinely unused exposure claim while the actual cell is still private.
pub fn cancel_original_header_exposure(cx:&mut StepContext<'_>,permit:&mut OriginalHeaderExposurePermit,cell:&OriginalEscrowHeaderLoanCell)->Result<bool,OriginalTurnFailure>{if permit.terminal_is_empty(){return Ok(true)}identity(permit)?;validate_observer(cx,permit,cell)?;if cell.is_exposed(){return Err(bad().into())}let(destination,extent)=cell.exposure_destination();if !permit.place.terminal_is_empty(){permit.place.qualify_sized(cx,destination,extent)?;if permit.place.capture_is_preissued(){if !permit.place.cancel_preissued_capture(cx,destination,extent)?{return Ok(false)}}else if !permit.place.settle_return(cx)?{return Ok(false)}}if !metadata(cx)?{return Ok(false)}permit.owner=0;permit.source=0;permit.destination=0;Ok(true)}


fn validate_observer(cx:&StepContext<'_>,permit:&OriginalHeaderExposurePermit,cell:&OriginalEscrowHeaderLoanCell)->Result<(),OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;if parent.source_identity()?!=permit.source||cell.exposure_destination().0!=permit.destination{return Err(bad().into())}Ok(())}
impl Drop for OriginalHeaderExposurePermit{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"header exposure requires actual Source observation or unused return")}}
